{
  "organization": {
    "name": "罗德岛 (Rhodes Island, ロドス・アイランド)",
    "type": ["制药公司", "建筑公司"],
    "leader":  ["博士","阿米娅"],
    "brief": "罗德岛制药公司，本部为一座大型陆行舰，是一个注册时间并不长，拥有完整武装力量和制药、科研技术的制药公司，专注于对矿石病病人的治疗。虽然罗德岛公司一直在制药，但是并没有公开卖药。与此同时，罗德岛也在致力于创建感染者与非感染者和平共处的社会，以及解决感染者引发的各种事件，抗击极端感染者组织整合运动。虽然罗德岛并没有成功研发出彻底治愈矿石病的技术，但是在罗德岛的努力下，许多感染者的病情都得到了控制。"
  },
  "members": {
    "ceo":  ["博士","阿米娅"],
