    "blood_bank_manager": "华法琳",
    "instructors": {
      "chief_instructor": "杜宾",
      "vanguard_instructor": "格瑞斯",
      "heavy_instructor": ["法伦", "坚雷"],
      "sniper_instructor": "苔丝",
      "caster_instructor": "维克多",
      "medical_instructor": "丽雅",
      "guard_instructor": "鞭刃"
    },
    "legal_advisors": ["但书", "斥罪"],
    "elite_operators": ["ACE（已殉职）", "Scout（已殉职）", "迷迭香", "煌", "术髓", "锋刃", "风暴眼", "触痕", "Misery", "Raidian", "Outcast（已殉职）", "Logos", "Mechanist", "Whitesmith（已殉职）"],
